SELECT MONTH(shipped_date) AS shipped_month, CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END AS shipped_cohort, COUNT(DISTINCT cost) AS unique_orders FROM shipments WHERE carrier = 'Kerry' AND status IN ('RETURNED', 'LOST') AND shipped_date <= '2023-09-03' GROUP BY ROLLUP(MONTH(shipped_date), CASE WHEN YEAR(shipped_date) < 2024 THEN 'before_2024' WHEN YEAR(shipped_date) = 2024 THEN '2024' ELSE 'after_2024' END) ORDER BY shipped_month, shipped_cohort DESC;
